const b=$input.first().json.body||$input.first().json;
const req=['siteId','conversationId','userId','message'];
const miss=req.filter(k=>!b[k]);
if(miss.length)throw new Error('Missing: '+miss.join(', '));
const rid=b.requestId||('req_'+Date.now()+'_'+Math.random().toString(36).slice(2,11));
return[{json:{
  siteId:b.siteId,
  conversationId:b.conversationId,
  userId:b.userId,
  message:b.message,
  pageUrl:b.pageUrl||null,
  uiContext:b.uiContext||{},
  requestId:rid,
  image:b.image||null
}}];

const inp=$('Validate Input').item.json;
const siteArr=$input.first().json;
const site=Array.isArray(siteArr)?siteArr[0]:siteArr;
if(!site)throw new Error('Site not found');

const repoUrl=site.repo_url||'';
const match=repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
const owner=match?match[1]:'';
const repo=match?match[2].replace(/\.git$/,''):'';

// SMART FILE SELECTION - No AI tokens needed!
const msg = inp.message.toLowerCase();
const filesToFetch = [];

// Color/Style changes
if (msg.match(/color|theme|style|css|background|gradient|dark|light/)) {
  filesToFetch.push('src/app/globals.css');
}

// Component-specific (also triggered by fix/error keywords)
if (msg.match(/header|nav|menu/) || (msg.match(/fix|error|broken|bug|issue/) && msg.match(/header/))) filesToFetch.push('src/components/Header.tsx');
if (msg.match(/hero|banner/)) filesToFetch.push('src/components/Hero.tsx');
if (msg.match(/footer/)) filesToFetch.push('src/components/Footer.tsx');
if (msg.match(/product|card/)) filesToFetch.push('src/components/ProductCard.tsx');
if (msg.match(/button|form|input/)) filesToFetch.push('src/app/page.tsx');

// For fix/error requests without specific component, load common files
if (msg.match(/fix|error|broken|bug|issue|conflict|merge/) && filesToFetch.length === 0) {
  filesToFetch.push('src/app/page.tsx');
  filesToFetch.push('src/app/globals.css');
}

// Page changes - always include page.tsx for general requests
if (msg.match(/page|layout|home|main/) || filesToFetch.length === 0) {
  if (!filesToFetch.includes('src/app/page.tsx')) filesToFetch.push('src/app/page.tsx');
}

// Limit to max 3 files to save tokens
const finalFiles = [...new Set(filesToFetch)].slice(0, 3);

return [{
  json: {
    ...inp,
    site: {
      id: site.id,
      name: site.name,
      repo_url: site.repo_url,
      default_branch: site.default_branch || 'main',
      stack: site.stack || 'unknown',
      owner, repo
    },
    fileContents: {},
    filesToFetch: finalFiles,
    owner, repo,
    branch: site.default_branch || 'main'
  }
}];

const ctx = $('Build Context').item.json;
const flyResp = $input.first().json;
return [{ json: { ...ctx, previewUrl: flyResp.previewUrl || '', previewStatus: flyResp.status || 'unknown' } }];

const ctx = $input.first().json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, fileContents: {} } }];
return files.map((f, idx) => ({ json: { ...ctx, currentFetchPath: f, fetchIndex: idx, totalFiles: files.length } }));

const prepareItems = $('Prepare Fetch').all();
const fetchItems = $input.all();
const originalCtx = $('Merge Fly Response').item.json;

const fileContents = {};
for (let i = 0; i < prepareItems.length; i++) {
  const path = prepareItems[i].json.currentFetchPath;
  const content = fetchItems[i]?.json?.content;
  if (path && content) {
    try {
      // FULL FILE CONTENT - no truncation! AI needs complete file to edit
      fileContents[path] = Buffer.from(content, 'base64').toString('utf8');
    } catch (e) {
      fileContents[path] = '// Error decoding file';
    }
  }
}

return [{ json: { ...originalCtx, fileContents } }];

// Handle multiple input formats
let input;
try {
  input = typeof query === 'string' ? JSON.parse(query) : query;
  if (input.input && typeof input.input === 'string') input = JSON.parse(input.input);
} catch (e) { return JSON.stringify({ error: 'Invalid JSON' }); }

const filePath = input.filePath || input.path;
const content = input.content;
if (!filePath || typeof content !== 'string') return JSON.stringify({ error: 'Need filePath and content' });

let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}

const siteId = ctx.siteId || ctx.site?.id;
const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || ctx.site?.default_branch || 'main';

if (!owner || !repo) return JSON.stringify({ error: 'Missing repo' });

try {
  // Instant HMR
  if (siteId) {
    try {
      await this.helpers.httpRequest({
        method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/write',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ siteId, filePath, content }), timeout: 5000
      });
    } catch (e) {}
  }
  // GitHub commit
  let sha = null;
  try {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
      headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
    });
    sha = existing.sha;
  } catch (e) {}
  const body = { message: (sha ? 'Update ' : 'Create ') + filePath, content: Buffer.from(content).toString('base64'), branch };
  if (sha) body.sha = sha;
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return JSON.stringify({ success: true, file: filePath });
} catch (e) {
  return JSON.stringify({ error: e.message });
}

let filePath = '';
try {
  let input = typeof query === 'string' ? query : JSON.stringify(query);
  if (input.includes('input')) { const p = JSON.parse(input); if (p.input) input = p.input; }
  try { const o = JSON.parse(input); filePath = o.filePath || o.path || o.input || ''; } catch (e) { filePath = input; }
  filePath = filePath.trim().replace(/^["']|["']$/g, '');
} catch (e) { filePath = String(query).trim(); }
if (!filePath) return JSON.stringify({ error: 'path required' });

let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}
const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || 'main';
if (!owner || !repo) return JSON.stringify({ error: 'no repo' });

try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });
  return r.content ? Buffer.from(r.content, 'base64').toString('utf8') : JSON.stringify({ error: 'empty' });
} catch (e) { return JSON.stringify({ error: e.message }); }

let ctx = {};
try { ctx = $('Merge Files')?.item?.json || {}; } catch (e) {}
const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || 'main';
if (!owner || !repo) return JSON.stringify({ error: 'no repo' });
try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' }
  });
  const files = (r.tree || []).filter(f => f.type === 'blob' && f.path.startsWith('src/')).map(f => f.path).slice(0, 30);
  return JSON.stringify(files);
} catch (e) { return JSON.stringify({ error: e.message }); }

const ctx = $('Merge Files').item.json;
const raw = $('AI Agent').item.json;
let out = raw?.output || raw?.text || '';
if (typeof out === 'object') out = JSON.stringify(out);

const filesCreated = [];
const steps = raw?.intermediateSteps || [];

for (const step of steps) {
  const action = step?.action;
  const obs = step?.observation || '';
  if (action?.tool === 'create_file') {
    try {
      const o = typeof obs === 'string' ? JSON.parse(obs) : obs;
      if (o.success && o.file) filesCreated.push(o.file);
    } catch (e) {
      try {
        const inp = typeof action.toolInput === 'string' ? JSON.parse(action.toolInput) : action.toolInput;
        if (inp.filePath) filesCreated.push(inp.filePath);
      } catch (e2) {}
    }
  }
}

const plan = {
  humanSummary: out || (filesCreated.length ? 'Updated: ' + filesCreated.join(', ') : 'Processed'),
  fileTargets: filesCreated.map(f => ({ path: f })),
  warnings: filesCreated.length === 0 && steps.length > 0 ? ['No files created'] : []
};

return [{ json: { ...ctx, plan, filesCreated, iterations: steps.length } }];

const ctx = $input.first().json;
if (!ctx?.site) throw new Error('Missing site');
if (!ctx?.plan) throw new Error('Missing plan');
return [{ json: ctx }];

const ctx = $('Guardrails').item.json;
const pullResp = $input.first().json;
return [{ json: { ...ctx, filesChanged: ctx.filesCreated || [], pullOk: pullResp.ok !== false } }];
